92	// another. Owns its own contact state, scoped to the one client it is showing; talks to that
93	// client's own /api/clients/<id>/contacts endpoints.
94	function ClientContacts({ client }: { client: Client }) {
95	  const [contacts, setContacts] = useState<Contact[]>([]);
96	  const [name, setName] = useState('');
97	  const [email, setEmail] = useState('');
98	  const [role, setRole] = useState('');
99	  const [emailError, setEmailError] = useState('');
100	
101	  async function load() {
102	    const res = await fetch(`/api/clients/${client.id}/contacts`);
103	    setContacts(await res.json());
104	  }
105	
106	  useEffect(() => {
107	    void load();
108	  }, [client.id]);
109	
110	  async function submit(e: React.FormEvent) {
111	    e.preventDefault();
112	    if (!name.trim() || !email.trim() || !role.trim()) {
