123	      headers: { 'Content-Type': 'application/json' },
124	      body: JSON.stringify({ name, email, role }),
125	    });
126	    setName('');
127	    setEmail('');
128	    setRole('');
129	    await load();
130	  }
131	
132	  // Pick this contact as the client's one main contact, then refresh so the new primary shows.
133	  async function makePrimary(id: number) {
134	    await fetch(`/api/contacts/${id}/primary`, { method: 'POST' });
