177	              <td data-testid="contact-email">{ct.email}</td>
178	              <td data-testid="contact-role">{ct.role}</td>
179	              <td>
180	                <button
181	                  data-testid={`contact-primary-${ct.id}`}
182	                  onClick={() => makePrimary(ct.id)}
183	                >
184	                  Make primary
185	                </button>
186	              </td>
187	            </tr>
188	          ))}
189	        </tbody>
190	      </table>
191	    </section>
192	  );
193	}
