195	// A client's detail: the projects being done for them. Owns its own project state, scoped to the one
196	// client it is showing. Reuses the project-row-<id>/project-name anchors in a client-scoped table.
197	// Shows only the client's ACTIVE projects by default (scope=active); the show-all toggle asks the
198	// server for everything (scope=all), so the finished and hidden (archived) ones appear too.
199	function ClientProjects({ client }: { client: Client }) {
200	  const [projects, setProjects] = useState<Project[]>([]);
201	  const [showAll, setShowAll] = useState(false);
202	
203	  useEffect(() => {
204	    async function load() {
