234	function ClientsPage() {
235	  const [clients, setClients] = useState<Client[]>([]);
236	  const [name, setName] = useState('');
237	  const [email, setEmail] = useState('');
238	  const [emailError, setEmailError] = useState('');
239	  // Client-side name filter: the list can get long, so a search box narrows it. Case-insensitive
240	  // substring match on the client name; an empty box shows everyone.
241	  const [search, setSearch] = useState('');
242	  const [openId, setOpenId] = useState<number | null>(null);
243	
244	  async function load() {
245	    const res = await fetch('/api/clients');
246	    setClients(await res.json());
247	  }
248	
249	  useEffect(() => {
250	    void load();
251	  }, []);
252	
253	  async function submit(e: React.FormEvent) {
254	    e.preventDefault();
255	    if (!EMAIL_RE.test(email.trim())) {
256	      setEmailError('Enter a valid email address.');
257	      return;
258	    }
259	    setEmailError('');
260	    await fetch('/api/clients', {
261	      method: 'POST',
262	      headers: { 'Content-Type': 'application/json' },
263	      body: JSON.stringify({ name, email }),
